quests[12308] = { id = 12308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!", sourceObjective = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", completion = "Worgen.  Blasted, Light-forsaken, filth-ridden worgen.\n\nIt's time we showed the locals what us civilized folk do with beasts like them.", sourceObjectiveStatus = "unverified-source-field" }
quests[12309] = { id = 12309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Durkon!", description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested assistance. You will find him and help him, {name}. The crypt is on the western border of the town square.", sourceObjective = "Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight.", completion = "Oh brother, it's a mess down there! I barely made it out last time - which is what prompted my request to the High Commander.\n\n<Durkon looks you up and down.>\n\nYou got that crazy look in your eyes, {race}. Thankfully, you're gonna need to be crazy to do what I'm about to ask of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12310] = { id = 12310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Response", description = "Our response must be immediate.  Decisive.  We must teach these savages not to cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.", sourceObjective = "Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters.", completion = "It's a shame those trappers turned out to be... afflicted.  We sure could've used a few more fighting men.\n\nMay the poor souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[12311] = { id = 12311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Noble's Crypt", description = "Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!\n\nAnd {name}, be on the lookout for any information that might be laying about inside the room where Amarion resides.", sourceObjective = "Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.", completion = "Now if we could stop the Scourge attacks coming from outside the keep we might be able to send help to Lord Fordragon at the Wrathgate.", sourceObjectiveStatus = "unverified-source-field" }
quests[12312] = { id = 12312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Scourge", description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.\n\nDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.", sourceObjective = "Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight.", progress = "A Scourge tome?", completion = "Whatever information is held in this book must be of great importance! I could hear the howls and wails echoing through the crypt as you made your escape!\n\nThe High Commander must be notified!", sourceObjectiveStatus = "unverified-source-field" }
quests[12314] = { id = 12314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With Captain Zorna!", description = "The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, {name}, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.", sourceObjective = "Slay Captain Zorna and report to Baron Freeman at Venture Bay.", completion = "Well done, {name}! Without their leader, the Horde is weak and disorganized. I will order our men forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[12315] = { id = 12315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Captain Brightwater!", description = "With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!\n\nThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.\n\nThis will be no easy fight, {name}. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!", sourceObjective = "Slay Captain Brightwater and report to General Khazgar at Venture Bay.", progress = "Have you eliminated the enemy captain?", completion = "You are a true soldier of the Horde, {name}. Your bravery will inspire my men to victory!", sourceObjectiveStatus = "unverified-source-field" }
quests[12316] = { id = 12316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay!", description = "We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.\n\nGo into the field, {name}, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!", sourceObjective = "Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.", completion = "Your bravery has inspired the men of the Westfall Brigade. Even now they fight with greater ferocity. The port will soon be ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[12317] = { id = 12317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay", description = "This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, {name}. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We don't want to keep Conqueror Krenna waiting.", sourceObjective = "Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.", progress = "Have you done as ordered?", completion = "The port will soon fall to us. You have done well this day, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot!  The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths.  Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths.  He'll know more of Direbrew's plot.\n\nFind our spy.  Save Brewfest!", sourceObjective = "Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.", completion = "You're from the Brewfest camp? Glory day!  Brewfest may yet be saved.\n\n{name}, Coren Direbrew must be stopped!  We cannot let him sabotage our sacred holiday.  Our brews must flow!", sourceObjectiveStatus = "unverified-source-field" }
quests[12319] = { id = 12319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Tome", description = "What can it be, {name}? That was certainly no ordinary curse that the blasted lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.", sourceObjective = "Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", progress = "The necrolord is no more?", completion = "<Halford's eyes widen.>\n\nThe fates smile down upon us on this day, {name}. I know just the person to see about this tome.", sourceObjectiveStatus = "unverified-source-field" }
quests[12320] = { id = 12320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Language of Death", description = "Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.\n\nGo now!", sourceObjective = "Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.", progress = "You come from high command, my son?", completion = "Perhaps, with proper motivation, Godfrey will tell us what he knows about the tome.\n\n<Hallard turns to Mayor Godfrey.>\n\nIsn't that right, mayor?", sourceObjectiveStatus = "unverified-source-field" }
quests[12321] = { id = 12321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Righteous Sermon", description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.", sourceObjective = "Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.", completion = "We should have known about the damned mausoleum. This is preposterous! Duke August Foehammer and Ambo Cash will be dispatched to the front lines in preparation for our next assault.\n\nOnce you have cleared the mines I will send you to Foehammer so that we may begin our attack against the Scourge of Naxxramas!\n\nThe information you have garnered thus far will be sent to Lord Fordragon at the Wrathgate upon the wings of our most able gryphon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12323] = { id = 12323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.", sourceObjective = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.", progress = "Have you smoked out the last of the Venture Company guys yet?", completion = "Well done, soldier! Now the rest of the men can focus their efforts on the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12324] = { id = 12324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.", sourceObjective = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.", progress = "Have you smoked out the last of the Venture Company vermin yet?", completion = "The general will be pleased that you've dealt with the Venture Company problem. Now, the men can focus on beating back the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12325] = { id = 12325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Hostile Territory", description = "You have done much to advance our efforts against the Scourge, {name}. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!", sourceObjective = "Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight.", completion = "Ah, the distinguished hero arrives. Welcome to ground zero, {name}. Allow me to bring you up to speed!\n\nThel'zan's most powerful forces have made their way into the Wintergarde Mausoleum. They plumb its depths in search of corpses and souls to send against Wintergarde while Naxxramas rains down terrible Scourge plague machines, set to hold us at bay!\n\nWe must strike now and hope that Lord Fordragon is able to hold out at the Wrathgate for just a little longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12326] = { id = 12326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steamtank Surprise", description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.", sourceObjective = "Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.", progress = "Name's Cash. Ambo Cash. And the pleasure is all yours.", completion = "Why I'm not wearing any pants isn't important. Let's just say I took some Scourge shrapnel in the wrong place and leave it at that, ok?\n\nSo you wiped out those plague wagons up in the fields and got my soldiers here in one piece. Impressive. You're one of the first to make it this far, friend. Too bad you gotta go right back out into the Carrion Fields. Yep, we've had a bit of a setback.", sourceObjectiveStatus = "unverified-source-field" }
quests[12327] = { id = 12327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Body Experience", description = "Ah, you seek a vision of the past.  You're a wise {race}.\n\nEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.", sourceObjective = "Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past.", progress = "Yes, {name}?", completion = "Did you learn anything from your vision?  You mentioned Solstice Village during your trance -- which marks the second time someone has spoken the place's name today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12328] = { id = 12328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna's Request", description = "I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.\n\nI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.", sourceObjective = "Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.", progress = "Did you obtain the dust, {name}?", completion = "Good.  These will do just fine.\n\nI will have the potion ready for you in no time at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12329] = { id = 12329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate and Coincidence", description = "There are two types of people in this world, {name}.  Those who believe in coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.\n\nEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.", sourceObjective = "Speak to Sasha at the White Pine Trading Post.", completion = "I was wondering when you'd turn up.  Think you can give me a hand here?", sourceObjectiveStatus = "unverified-source-field" }
quests[12330] = { id = 12330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatoly Will Talk", description = "My sister is here somewhere, and I can't seem to get this monster to talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.\n\nTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.\n\nI will help you find the person behind all this once we save my sister.", sourceObjective = "Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village. Bring Tatjana back to the White Pine Trading Post.", progress = "I'm glad to see you in one piece.", completion = "That... that was close.\n\nWe need to save Anya.  Now!", sourceObjectiveStatus = "unverified-source-field" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12332] = { id = 12332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12333] = { id = 12333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
